package com.signalpay.demo;
import static org.junit.Assert.*;
import android.Manifest;
import android.net.Uri;
import androidx.test.ext.junit.rules.ActivityScenarioRule;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.rule.GrantPermissionRule;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.runner.RunWith;
@RunWith(AndroidJUnit4.class)
public class DemoWebViewTest {
 @Rule public GrantPermissionRule permission=GrantPermissionRule.grant(Manifest.permission.CAMERA);
 @Rule public ActivityScenarioRule<MainActivity> activity=new ActivityScenarioRule<>(MainActivity.class);
 private String js(String script)throws Exception{AtomicReference<String> result=new AtomicReference<>();CountDownLatch done=new CountDownLatch(1);activity.getScenario().onActivity(s->s.getDemoWebView().evaluateJavascript(script,v->{result.set(v);done.countDown();}));assertTrue(done.await(10,TimeUnit.SECONDS));return result.get();}
 private void until(String expression)throws Exception{long end=System.currentTimeMillis()+45000;while(System.currentTimeMillis()<end){if("true".equals(js(expression)))return;Thread.sleep(150);}fail("Condition not reached: "+expression+" auth="+js("document.getElementById('authError').textContent")+" app="+js("document.getElementById('appError').textContent"));}
 private void async(String expression)throws Exception{js("window.testDone=false;window.testError='';Promise.resolve().then(async()=>{"+expression+"}).then(()=>window.testDone=true).catch(e=>{window.testError=e.message;window.testDone=true})");until("window.testDone===true");assertEquals("\"\"",js("window.testError"));}
 private void loginAdil()throws Exception{js("if(!document.getElementById('registerForm').hidden)document.getElementById('toggleAuth').click();document.getElementById('loginMobile').value='+923001110101';document.getElementById('loginPin').value='63728495';document.getElementById('loginForm').requestSubmit()");until("!document.getElementById('appContent').hidden");}
 @Before public void ready()throws Exception{until("document.readyState==='complete'&&!!window.SignalAuthCrypto&&(!document.getElementById('authScreen').hidden||!document.getElementById('appContent').hidden)");if("true".equals(js("!document.getElementById('appContent').hidden"))){js("document.getElementById('logout').click()");}if("true".equals(js("!document.getElementById('registerForm').hidden"))){js("document.getElementById('registerName').value='Adil';document.getElementById('registerMobile').value='+923001110101';document.getElementById('registerPin').value='63728495';document.getElementById('confirmPin').value='63728495';document.getElementById('registerForm').requestSubmit()");until("!document.getElementById('appContent').hidden");}else loginAdil();}
 @Test public void encryptedAccountPersistsAcrossRestartAndRequiresPin()throws Exception{String id=js("document.getElementById('accountId').textContent"),qr=js("document.querySelector('#accountQR img').src");js("window.testOldDocument=true;location.reload()");until("!window.testOldDocument&&document.readyState==='complete'&&!document.getElementById('authScreen').hidden");assertEquals("true",js("document.getElementById('appContent').hidden&&document.getElementById('accountName').textContent===''") );loginAdil();assertEquals(id,js("document.getElementById('accountId').textContent"));assertEquals(qr,js("document.querySelector('#accountQR img').src"));async("const w=await store.read();if(w.privateKey.extractable)throw Error('Exportable runtime key');await SignalAccounts.auditWallet(w);if((await vault.profile()).phoneVerified)throw Error('OTP falsely verified');");}
 @Test public void realAccountPngResolvesSavedRecipientAndPendingConfirmation()throws Exception{async("window.peer=await SignalAccounts.createWallet('Native receiver');const image=makeQR(peer.accountQR,'Test QR');await new Promise((resolve,reject)=>{if(image.complete){resolve();return;}image.onload=resolve;image.onerror=reject;});const canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;canvas.getContext('2d').drawImage(image,0,0);const raw=SignalScanner.decode(canvas,jsQR);if(raw!==peer.accountQR)throw Error('QR decoder mismatch');view('send');await showDecoded(raw,'Native QR');");until("document.getElementById('amountDialog').open");assertEquals("true",js("document.getElementById('receiverName').textContent==='Native receiver'&&document.getElementById('receiverId').textContent===peer.account.id"));js("document.getElementById('recipientChecked').checked=true");js("document.getElementById('useNearby').checked=false;document.getElementById('amount').value='100';document.getElementById('paymentForm').requestSubmit()");until("document.getElementById('reviewDialog').open");js("document.getElementById('confirmPayment').click();document.getElementById('confirmPayment').click()");until("!document.getElementById('screen-transfer').hidden&&document.getElementById('transferStatus').textContent==='Pending'");async("const w=await store.read();const rows=w.transactions.filter(t=>t.peer.id===peer.account.id);if(rows.length!==1||rows[0].status!=='Pending'||rows[0].cents!==10000)throw Error('Duplicate confirmation');");}
 @Test public void signedOfflineDeliveryAndDuplicateProtection()throws Exception{async("const A=SignalAccounts;let s=await A.createWallet('Usama'),r=await A.createWallet('Adil');s=A.addOutgoing(s,await A.prepareOffer(s,r.accountQR,10000,'offline'));if(s.balance!==2500000||A.available(s)!==2490000)throw Error('Pending reserve');const p=await A.prepareIncoming(r,s.transactions[0].offerRaw,'accepted');r=A.addIncoming(r,p);r=A.addIncoming(r,p);const receipt=await A.prepareReceipt(s,r.transactions[0].receiptRaw);s=A.finishOutgoing(s,receipt);s=A.finishOutgoing(s,receipt);if(s.balance!==2490000||r.balance!==2510000||s.transactions[0].id!==r.transactions[0].id)throw Error('Transfer mismatch');");}
 @Test public void cameraStartsAndStopsAfterPinLogin()throws Exception{js("document.getElementById('scanQR').click()");until("!!document.getElementById('video').srcObject&&document.getElementById('video').readyState>=2");js("window.testTrack=document.getElementById('video').srcObject.getVideoTracks()[0];document.getElementById('stopCamera').click()");until("testTrack.readyState==='ended'&&document.getElementById('video').srcObject===null");}
 @Test public void nativeSoundboxAndMute()throws Exception{assertEquals("true",js("!!window.SignalSoundbox&&!!window.SignalQR"));activity.getScenario().onActivity(s->s.lastSpeechText="");js("document.getElementById('testSound').click()");AtomicReference<String> spoken=new AtomicReference<>("");for(int i=0;i<60;i++){activity.getScenario().onActivity(s->spoken.set(s.lastSpeechText));if(spoken.get().contains("100"))break;Thread.sleep(100);}assertTrue(spoken.get().contains("100")&&spoken.get().contains("simulation"));activity.getScenario().onActivity(s->s.lastSpeechText="");js("document.getElementById('soundEnabled').checked=false;document.getElementById('testSound').click()");activity.getScenario().onActivity(s->spoken.set(s.lastSpeechText));assertEquals("",spoken.get());}
 @Test public void logoutAndWrongPinHidePrivateWallet()throws Exception{js("document.getElementById('logout').click()");until("!document.getElementById('authScreen').hidden");assertEquals("true",js("document.getElementById('accountQR').textContent===''&&document.getElementById('activityRows').textContent===''&&document.getElementById('accountName').textContent===''") );js("document.getElementById('loginMobile').value='+923001110101';document.getElementById('loginPin').value='94583726';document.getElementById('loginForm').requestSubmit()");until("document.getElementById('authError').textContent.includes('incorrect')");assertEquals("true",js("document.getElementById('appContent').hidden"));loginAdil();}
 @Test public void invalidQrAndUntrustedOriginsFailClosed()throws Exception{assertFalse(MainActivity.isLocal(Uri.parse("https://evil.example/assets/www/index.html")));assertFalse(MainActivity.isExternalAllowed(Uri.parse("https://github.com/other/repo/releases/latest")));async("let rejected=false;try{await SignalAccounts.verify('SIGNALPAY-TEST-123')}catch(e){rejected=true}if(!rejected)throw Error('Invalid QR accepted');");}

 @Test public void inAppUpdatesUseNativeBridgeAndRejectUnverifiedOrOlderMetadata()throws Exception{
  assertEquals("true",js("!!window.SignalUpdater"));
  String current=BuildConfig.VERSION_NAME.replace("-debug", "");
  String future="{\"verified\":true,\"version\":\"99.0.0\",\"url\":\"https://github.com/usama-hussain-seo-spciealist/signal-app/releases/download/android-v99.0.0/SignalPay-demo-99.0.0.apk\",\"sha256\":\""+new String(new char[64]).replace("\0", "a")+"\",\"bytes\":1500000}";
  activity.getScenario().onActivity(a->a.updateFetcher=()->future);
  js("document.getElementById('openUpdates').click()");until("!document.getElementById('updateAPK').hidden");
  assertEquals("\""+current+"\"",js("document.getElementById('installedVersion').textContent"));
  assertEquals("true",js("document.getElementById('updateAPK').getAttribute('href').endsWith('SignalPay-demo-99.0.0.apk')"));
  String same=future.replace("99.0.0",current);activity.getScenario().onActivity(a->a.updateFetcher=()->same);
  js("document.getElementById('checkUpdates').click()");until("document.getElementById('updateStatus').textContent.includes('up to date')");assertEquals("true",js("document.getElementById('updateAPK').hidden"));
  activity.getScenario().onActivity(a->a.updateFetcher=()->future.replace("\"verified\":true","\"verified\":false"));
  js("document.getElementById('checkUpdates').click()");until("document.getElementById('updateStatus').textContent.includes('has not been verified')");assertEquals("true",js("document.getElementById('updateAPK').hidden"));
  activity.getScenario().onActivity(a->a.updateFetcher=()->{throw new java.io.IOException("offline");});
  js("document.getElementById('checkUpdates').click()");until("document.getElementById('updateStatus').textContent.includes('internet')");assertEquals("true",js("document.getElementById('updateAPK').hidden"));
  js("document.getElementById('closeUpdates').click()");assertEquals("true",js("!document.getElementById('appContent').hidden"));
 }
}
